ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS health_conditions text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS liked_recipe_ids uuid[] NOT NULL DEFAULT '{}';

CREATE TABLE public.recipes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  region text NOT NULL,
  course text NOT NULL,
  diet_type text NOT NULL CHECK (diet_type IN ('vegetarian','non_vegetarian','vegan','eggetarian')),
  meal_types text[] NOT NULL DEFAULT '{}',
  audience text NOT NULL DEFAULT 'adult' CHECK (audience IN ('adult','baby')),
  min_age_months int,
  max_age_months int,
  prep_minutes int NOT NULL DEFAULT 10,
  cook_minutes int NOT NULL DEFAULT 20,
  servings int NOT NULL DEFAULT 2,
  serving_size text NOT NULL,
  calories numeric NOT NULL,
  protein numeric NOT NULL,
  carbohydrates numeric NOT NULL,
  fat numeric NOT NULL,
  fiber numeric NOT NULL DEFAULT 0,
  sugar numeric NOT NULL DEFAULT 0,
  sodium numeric NOT NULL DEFAULT 0,
  allergens text[] NOT NULL DEFAULT '{}',
  suitable_for text[] NOT NULL DEFAULT '{}',
  texture text NOT NULL DEFAULT 'regular',
  flavors text[] NOT NULL DEFAULT '{}',
  key_ingredients text[] NOT NULL DEFAULT '{}',
  ingredients text[] NOT NULL DEFAULT '{}',
  steps text[] NOT NULL DEFAULT '{}',
  tips text NOT NULL DEFAULT '',
  image text NOT NULL DEFAULT 'dishes'
);
CREATE INDEX recipes_audience_idx ON public.recipes(audience);
GRANT SELECT ON public.recipes TO anon, authenticated;
GRANT ALL ON public.recipes TO service_role;
ALTER TABLE public.recipes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "recipes are public" ON public.recipes FOR SELECT TO anon, authenticated USING (true);

CREATE TABLE public.children (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 60),
  birth_date date NOT NULL,
  diet_type text NOT NULL DEFAULT 'vegetarian' CHECK (diet_type IN ('vegetarian','non_vegetarian','vegan','eggetarian')),
  allergies text[] NOT NULL DEFAULT '{}',
  likes text[] NOT NULL DEFAULT '{}',
  dislikes text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX children_user_idx ON public.children(user_id);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.children TO authenticated;
GRANT ALL ON public.children TO service_role;
ALTER TABLE public.children ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own children select" ON public.children FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "own children insert" ON public.children FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own children update" ON public.children FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own children delete" ON public.children FOR DELETE TO authenticated USING (auth.uid() = user_id);

CREATE OR REPLACE FUNCTION public.validate_child() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NEW.birth_date > current_date THEN RAISE EXCEPTION 'Birth date cannot be in the future'; END IF;
  IF NEW.birth_date < current_date - interval '6 years' THEN RAISE EXCEPTION 'Baby Corner supports children up to 6 years'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER children_validate BEFORE INSERT OR UPDATE ON public.children FOR EACH ROW EXECUTE FUNCTION public.validate_child();

INSERT INTO public.recipes (slug,name,description,region,course,diet_type,meal_types,audience,prep_minutes,cook_minutes,servings,serving_size,calories,protein,carbohydrates,fat,fiber,sugar,sodium,allergens,suitable_for,texture,flavors,key_ingredients,ingredients,steps,tips,image)
SELECT trim(both '-' from lower(regexp_replace(n,'[^a-zA-Z0-9]+','-','g'))), n, de, r, co,
  CASE d WHEN 'vg' THEN 'vegan' WHEN 'v' THEN 'vegetarian' WHEN 'e' THEN 'eggetarian' ELSE 'non_vegetarian' END,
  array_remove(ARRAY[
    CASE WHEN position('B' in m)>0 THEN 'breakfast' END,
    CASE WHEN position('L' in m)>0 THEN 'lunch' END,
    CASE WHEN position('D' in m)>0 THEN 'dinner' END,
    CASE WHEN position('S' in m)>0 THEN 'snack' END], NULL),
  'adult', pm, cm, sv, ss, k, p, cb, f, fi, su, na,
  CASE WHEN a='' THEN '{}'::text[] ELSE string_to_array(a,'|') END,
  CASE WHEN s='' THEN '{}'::text[] ELSE string_to_array(s,'|') END,
  tx,
  string_to_array(fl,'|'), string_to_array(ki,'|'), string_to_array(ing,'|'), string_to_array(st,'|'), tip, img
FROM (VALUES
('Idli with Sambar','Steamed fermented rice-lentil cakes with a vegetable lentil stew.','South Indian','Breakfast','vg','B',20,25,4,'3 idli + 1 cup sambar (330g)',310,12,58,4,7,4,620,'','heart|senior','soft','mild|tangy','rice|urad dal|toor dal|vegetables','2 cups idli rice|1/2 cup urad dal|1/2 tsp fenugreek seeds|1/2 cup toor dal|1 cup mixed vegetables (drumstick, carrot, pumpkin)|1 tbsp sambar powder|Small lemon-size ball of tamarind|1 tsp mustard seeds, curry leaves, 1 tsp oil|Salt to taste','Soak rice and urad dal with fenugreek separately for 5 hours, grind to a smooth batter and ferment overnight|Add salt, pour into greased idli moulds and steam for 10-12 minutes|Pressure cook toor dal till soft and mash|Boil vegetables in tamarind water with sambar powder, add the dal and simmer 10 minutes|Temper mustard seeds and curry leaves in oil, pour over sambar and serve hot with idli','Fermentation improves digestibility and B-vitamin content.','dishes'),
('Ragi Dosa','Instant lacy finger-millet crepe, rich in calcium.','South Indian','Breakfast','vg','BD',10,15,3,'2 dosas (150g)',220,6,40,4,6,1,280,'','diabetes|weight_loss|heart','regular','savory','ragi|rice flour|onion','1 cup ragi flour|1/4 cup rice flour|1 small onion, finely chopped|1 green chilli, chopped|Coriander leaves|Salt and water as needed','Mix the flours with salt and water into a thin pourable batter|Stir in onion, chilli and coriander and rest 10 minutes|Pour batter from the edges of a hot tawa inward to form a lacy dosa|Drizzle a few drops of oil and cook until crisp. Serve with coconut chutney','Ragi has a low glycemic load and keeps blood sugar steady.','grains'),
('Pesarattu','Andhra green moong dosa packed with plant protein.','South Indian','Breakfast','vg','BD',15,15,3,'2 dosas (180g)',240,14,34,5,7,2,300,'','diabetes|weight_loss|high_protein|heart','regular','spicy|savory','green moong|ginger|rice','1 cup whole green moong, soaked 6 hours|2 tbsp rice|1 inch ginger|2 green chillies|1/2 tsp cumin|1 onion, chopped|Salt to taste','Grind soaked moong, rice, ginger, chillies and cumin to a slightly coarse batter|Add salt and water for a spreadable batter|Spread a ladleful on a hot tawa and sprinkle chopped onion|Drizzle oil and cook both sides till golden. Serve with ginger chutney','No fermentation needed and high in protein.','legumes'),
('Vegetable Upma','Soft savoury semolina porridge with vegetables.','South Indian','Breakfast','vg','B',10,15,3,'1 cup (200g)',240,6,38,7,4,3,380,'gluten','senior','soft','mild|savory','semolina|vegetables|curry leaves','1 cup roasted rava (semolina)|1 cup chopped carrot, beans and peas|1 onion, chopped|1 tsp mustard seeds, 1 tsp urad dal|Curry leaves, 1 green chilli|1 tbsp oil|2.5 cups water, salt','Heat oil, splutter mustard seeds and urad dal, add curry leaves, chilli and onion|Add vegetables and saute 3 minutes|Pour in water with salt and bring to a boil|Add rava slowly while stirring to avoid lumps, cover and cook 3 minutes','Soft texture makes it easy to chew for older adults.','grains'),
('Ven Pongal','Comforting peppery rice and moong dal porridge.','South Indian','Breakfast','v','B',10,20,3,'1 cup (200g)',280,8,40,10,2.4,0.5,420,'dairy|tree_nuts','senior','soft','mild|savory','rice|moong dal|pepper|ghee','1/2 cup rice|1/4 cup split yellow moong dal|1 tsp black pepper, 1 tsp cumin|1 inch ginger, grated|Curry leaves|5 cashews|1.5 tbsp ghee|Salt','Dry roast moong dal till aromatic and wash with the rice|Pressure cook with 4 cups water and salt until very soft, mash lightly|Heat ghee, fry cashews, pepper, cumin, ginger and curry leaves|Pour the tempering over the pongal and mix','Use less ghee for heart health.','rice'),
('Bisi Bele Bath','Karnataka one-pot spiced rice, lentils and vegetables.','South Indian','Rice & Grains','vg','LD',15,30,4,'1.5 cups (300g)',350,11,58,8,8,4,650,'','senior','soft','spicy|tangy','rice|toor dal|vegetables|tamarind','1/2 cup rice|1/2 cup toor dal|2 cups mixed vegetables|2 tbsp bisi bele bath powder|Tamarind pulp from a small lemon-size ball|1 tsp mustard seeds, curry leaves|1 tbsp oil|Salt','Pressure cook rice and dal together with 5 cups water till mushy|Cook vegetables in tamarind water with spice powder and salt|Combine with the rice-dal and simmer to a porridge-like consistency|Temper mustard seeds and curry leaves and pour over','A complete cereal-pulse protein meal in one pot.','rice'),
('Tomato Rasam','Thin peppery tomato-tamarind soup that aids digestion.','South Indian','Soup & Salad','vg','LD',5,15,4,'1 cup (240ml)',60,2,10,1.5,1.5,3,450,'','weight_loss|heart|diabetes|senior','regular','tangy|spicy','tomato|tamarind|pepper|garlic','2 tomatoes, chopped|Small gooseberry-size tamarind|1 tsp rasam powder|1/2 tsp crushed pepper and cumin|3 garlic cloves, crushed|Curry leaves, coriander|1 tsp oil|Salt','Boil tomatoes in tamarind water with rasam powder, garlic and salt for 8 minutes|Add 2 cups water and heat until frothy, do not over boil|Temper mustard, cumin and curry leaves in oil|Add the tempering and coriander. Serve as a soup or with rice','Very low in calories and comforting when unwell.','vegetables'),
('Avial','Kerala mixed vegetables in coconut and curd.','South Indian','Dal & Curry','v','L',15,20,4,'1 cup (200g)',180,4,16,11,5,5,320,'dairy','diabetes|senior','soft','mild|tangy','mixed vegetables|coconut|curd','3 cups vegetables (drumstick, raw banana, yam, carrot, beans)|1/2 cup grated coconut|2 green chillies|1 tsp cumin|1/2 cup thick curd|1 tbsp coconut oil|Curry leaves, salt','Cook vegetables in a little water with turmeric and salt till just tender|Grind coconut, chillies and cumin coarsely|Add the paste and simmer 3 minutes|Turn off heat, stir in whisked curd, drizzle coconut oil and add curry leaves','High in fibre; keep coconut moderate for heart patients.','vegetables'),
('Kerala Fish Curry','Tangy red fish curry with Malabar tamarind.','South Indian','Dal & Curry','n','LD',15,25,4,'1 cup (220g)',260,24,8,15,2,3,560,'fish','high_protein|heart|diabetes','regular','spicy|tangy','fish|kokum|coconut|chilli','500 g fish (seer or sardine)|2 pieces kudampuli (Malabar tamarind)|1 tbsp Kashmiri chilli powder|1/2 tsp turmeric|1 tsp ginger-garlic paste|1/2 cup thin coconut milk|1 tbsp coconut oil|Curry leaves, salt','Soak kudampuli in warm water for 10 minutes|Saute ginger-garlic and curry leaves in coconut oil, add chilli and turmeric|Add kudampuli with its water and salt and bring to a boil|Slide in the fish, simmer 10 minutes and finish with coconut milk','Oily fish supply omega-3 fats that support heart health.','fish'),
('Chettinad Chicken','Peppery Tamil chicken curry with roasted spices.','South Indian','Dal & Curry','n','LD',20,35,4,'1 cup (200g)',290,28,8,16,2,3,600,'','high_protein|diabetes','regular','spicy','chicken|pepper|fennel|onion','500 g skinless chicken|2 onions, 2 tomatoes|1 tbsp black pepper, 1 tsp fennel, 4 dry red chillies, 1 tsp coriander seeds|1 tbsp ginger-garlic paste|2 tbsp grated coconut|1.5 tbsp oil|Curry leaves, salt','Dry roast the whole spices and coconut, then grind to a paste|Saute onions and curry leaves in oil till golden, add ginger-garlic and tomatoes|Add chicken and the masala paste and mix well|Cover and cook 25 minutes until tender','Skinless chicken keeps it lean and high in protein.','meat'),
('Lemon Rice','Tangy turmeric rice with crunchy peanuts.','South Indian','Rice & Grains','vg','L',10,10,3,'1 cup (180g)',270,5,46,8,2,1,380,'peanut','','regular','tangy|mild','rice|lemon|peanut','2 cups cooked rice, cooled|2 tbsp lemon juice|2 tbsp peanuts|1 tsp mustard seeds, 1 tsp chana dal|1/2 tsp turmeric|Curry leaves, green chilli|1 tbsp oil, salt','Heat oil and fry peanuts till crisp|Add mustard, chana dal, chilli, curry leaves and turmeric|Turn off heat, add rice, salt and lemon juice|Mix gently and rest 10 minutes for the flavours to blend','Great lunch-box option.','rice'),
('Curd Rice','Cooling probiotic rice with tempered curd.','South Indian','Rice & Grains','v','LD',5,5,2,'1 cup (200g)',230,6,36,6,0.8,4,300,'dairy','senior','soft','mild','rice|curd|ginger','1 cup soft cooked rice|3/4 cup fresh curd|2 tbsp milk|1/2 inch ginger, grated|1 tsp mustard seeds, curry leaves|1 tsp oil, salt|Pomegranate or grated carrot (optional)','Mash the rice lightly while warm and let cool|Mix in curd, milk, salt and ginger|Temper mustard and curry leaves in oil and pour over|Garnish with pomegranate or carrot','Probiotic and soothing - a gentle dinner for elders.','rice'),
('Egg Curry','Boiled eggs simmered in onion-tomato coconut gravy.','South Indian','Dal & Curry','e','LD',10,25,3,'2 eggs with gravy (220g)',260,14,10,18,2,4,520,'egg','high_protein|diabetes','regular','spicy','egg|onion|tomato|coconut','6 boiled eggs|2 onions, 2 tomatoes|1 tbsp ginger-garlic paste|1 tsp chilli, 1 tsp coriander, 1/2 tsp garam masala|1/4 cup coconut milk|1 tbsp oil|Curry leaves, salt','Saute onions till golden and add ginger-garlic|Add tomatoes and spices and cook to a thick masala|Add water and coconut milk and simmer 5 minutes|Add halved boiled eggs and cook 5 minutes more','Eggs are an affordable complete protein.','eggs'),
('Hyderabadi Chicken Biryani','Fragrant layered dum biryani with marinated chicken.','South Indian','Rice & Grains','n','LD',30,45,5,'1.5 cups (300g)',480,26,58,15,2.5,3,720,'dairy|tree_nuts','high_protein','regular','spicy|savory','rice|chicken|curd|saffron','2 cups basmati rice, soaked|500 g chicken|1 cup curd|2 onions, thinly sliced and fried|1 tbsp ginger-garlic paste, 1 tbsp biryani masala|Mint, coriander, saffron soaked in milk|2 tbsp ghee, whole spices, salt','Marinate chicken in curd, ginger-garlic, masala, mint and salt for 1 hour|Parboil rice with whole spices till 70 percent cooked|Layer chicken, fried onions, rice, saffron milk and herbs in a heavy pot|Seal and cook on low heat (dum) for 30 minutes','Pair with raita and salad; keep the portion to one cup if managing weight.','rice'),
('Kosambari','Karnataka moong dal and cucumber salad.','South Indian','Soup & Salad','vg','LS',10,0,3,'1 bowl (150g)',130,7,18,3,5,3,200,'','weight_loss|diabetes|heart|hypertension|high_protein','regular','tangy|mild','moong dal|cucumber|carrot|coconut','1/2 cup split moong dal, soaked 2 hours|1 cucumber, 1 carrot, finely chopped|2 tbsp grated coconut|1 green chilli|1 tbsp lemon juice|Mustard seed tempering, coriander, salt','Drain the soaked dal well|Mix with cucumber, carrot, coconut and chilli|Add lemon juice and salt just before serving|Pour a mustard seed tempering on top','Raw soaked dal keeps it crunchy, light and filling.','vegetables'),
('Ragi Ladoo','Calcium-rich finger-millet sweet with jaggery.','South Indian','Dessert','v','S',10,15,8,'1 ladoo (35g)',140,3,20,6,2,9,10,'dairy','senior','regular','sweet','ragi|jaggery|ghee','1 cup ragi flour|1/2 cup grated jaggery|3 tbsp ghee|Cardamom powder','Roast ragi flour in ghee on low heat for 8-10 minutes until aromatic|Cool slightly and mix in jaggery and cardamom|Shape into ladoos while warm|Store in an airtight jar for up to a week','A better sweet for children and elders; diabetics should limit.','sweets'),
('Dal Tadka','Yellow lentils finished with a garlic-cumin tempering.','North Indian','Dal & Curry','vg','LD',10,25,4,'1 cup (200g)',180,10,26,4,6,2,420,'','heart|diabetes|weight_loss|high_protein|senior','soft','spicy|savory','toor dal|tomato|garlic|cumin','1 cup toor dal|1 onion, 1 tomato, chopped|3 garlic cloves|1 tsp cumin seeds|1/2 tsp turmeric, 1 tsp red chilli|1 tbsp oil|Coriander, salt','Pressure cook dal with turmeric and 3 cups water for 3 whistles|Heat oil, splutter cumin and garlic, add onion and saute golden|Add tomato and chilli and cook till soft|Pour the tempering into the dal, simmer 5 minutes and add coriander','Lentils provide protein and soluble fibre that support heart health.','curry'),
('Rajma Masala','Punjabi kidney beans in a spiced tomato gravy.','North Indian','Dal & Curry','vg','LD',15,40,4,'1 cup (220g)',240,12,34,6,10,4,480,'','diabetes|heart|high_protein','regular','spicy|savory','kidney beans|tomato|onion','1 cup rajma, soaked overnight|2 onions, 3 tomatoes pureed|1 tbsp ginger-garlic paste|1 tsp each cumin, coriander and garam masala|1 tbsp oil|Salt, coriander','Pressure cook soaked rajma for 6-7 whistles until soft|Saute onion till brown, add ginger-garlic and spices|Add tomato puree and cook till the oil separates|Add rajma with cooking water and simmer 15 minutes, mashing a few beans','Very high fibre helps steady blood sugar.','curry'),
('Chana Masala','Tangy chickpea curry with amchur.','North Indian','Dal & Curry','vg','LD',15,40,4,'1 cup (200g)',270,12,38,8,10,5,520,'','diabetes|high_protein','regular','spicy|tangy','chickpeas|onion|tomato|amchur','1 cup kabuli chana, soaked overnight|2 onions, 2 tomatoes|1 tbsp chole masala|1 tsp amchur|1 tea bag (for colour)|1 tbsp oil|Ginger, green chilli, salt','Pressure cook chana with the tea bag and salt till soft|Saute onions, ginger and chilli, add tomatoes and masala|Add chana and some cooking water and simmer 15 minutes|Finish with amchur and coriander','Pair with phulka instead of bhatura for a lighter meal.','curry'),
('Palak Paneer','Cottage cheese in a smooth spinach gravy.','North Indian','Dal & Curry','v','LD',15,20,3,'1 cup (200g)',280,14,10,20,4,3,450,'dairy','diabetes|high_protein|senior','soft','mild|savory','spinach|paneer|garlic','4 cups spinach|150 g paneer, cubed|1 onion, 1 tomato|3 garlic cloves, 1 inch ginger|1/2 tsp cumin, 1/2 tsp garam masala|1 tbsp oil|2 tbsp low-fat milk, salt','Blanch spinach for 2 minutes, cool in cold water and puree|Saute cumin, garlic, ginger and onion, then add tomato|Add spinach puree, spices and salt and simmer 5 minutes|Add paneer and milk and cook 2 minutes more','Low-carb and rich in calcium and iron.','curry'),
('Baingan Bharta','Smoky fire-roasted mashed brinjal.','North Indian','Dal & Curry','vg','LD',10,25,3,'1 cup (180g)',130,3,14,7,6,6,350,'','weight_loss|diabetes|heart','soft','spicy|savory','brinjal|onion|tomato','1 large brinjal|1 onion, 2 tomatoes|2 green chillies, 3 garlic cloves|1/2 tsp red chilli, 1/2 tsp cumin|1 tbsp mustard oil|Coriander, salt','Roast brinjal over an open flame till the skin chars and the inside is soft|Peel and mash the flesh|Saute cumin, garlic, onion and chillies in oil, then add tomatoes|Add the mashed brinjal and spices and cook 5 minutes','Low in calories and high in fibre.','vegetables'),
('Tandoori Chicken','Oven-baked yogurt-marinated chicken.','North Indian','Main Course','n','LD',15,30,4,'2 pieces (180g)',260,32,5,12,1,3,620,'dairy','high_protein|weight_loss|diabetes','regular','spicy','chicken|curd|spices','500 g chicken legs, skinless and scored|1/2 cup hung curd|1 tbsp ginger-garlic paste|1 tbsp tandoori masala, 1 tsp Kashmiri chilli|1 tbsp lemon juice|1 tsp mustard oil|Salt','Mix curd, spices, lemon, oil and salt into a marinade|Coat the chicken well and refrigerate for at least 2 hours|Bake at 220 C for 25-30 minutes, turning once|Rest 5 minutes and serve with onion rings and lemon','Baking instead of frying keeps the fat low.','meat'),
('Mixed Veg Khichdi','Soft one-pot rice, moong dal and vegetables.','North Indian','Rice & Grains','v','LD',10,20,3,'1.5 cups (300g)',290,11,50,5,6,3,400,'dairy','senior|heart','soft','mild|savory','rice|moong dal|vegetables','1/2 cup rice|1/2 cup split moong dal|1 cup chopped vegetables (carrot, peas, beans)|1/2 tsp turmeric, 1 tsp cumin|1 tsp ghee|1 inch ginger|Salt','Wash rice and dal together|Heat ghee, add cumin, ginger and vegetables and saute briefly|Add rice, dal, turmeric, salt and 4 cups water|Pressure cook 4 whistles until soft and porridge-like','Easy to digest - ideal when unwell and for grandparents.','rice'),
('Vegetable Daliya','Broken-wheat porridge with vegetables.','North Indian','Breakfast','vg','BD',5,15,2,'1 bowl (220g)',220,7,40,3,7,3,300,'gluten','diabetes|weight_loss|heart|senior','soft','mild|savory','broken wheat|vegetables','1/2 cup daliya (broken wheat)|1 cup chopped vegetables|1/2 tsp cumin, grated ginger|1 tsp oil|Salt, 2.5 cups water','Dry roast daliya for 3 minutes|Saute cumin, ginger and vegetables in oil|Add daliya, salt and water|Pressure cook 3 whistles until soft','Whole grain with slow-release carbs.','grains'),
('Besan Chilla','Savoury gram-flour pancake with vegetables.','North Indian','Breakfast','vg','BS',5,10,2,'2 chillas (140g)',200,10,24,7,5,2,320,'','diabetes|weight_loss|high_protein|heart','regular','spicy|savory','besan|onion|tomato','1 cup besan|1 onion, 1 tomato, 1 green chilli, finely chopped|1/4 tsp turmeric, 1/2 tsp ajwain|Coriander leaves|1 tsp oil|Salt, water','Whisk besan with spices, salt and water into a smooth batter|Fold in the chopped vegetables|Spread a ladleful thin on a hot non-stick tawa|Cook with a few drops of oil until golden on both sides','Quick, gluten-free and high in protein.','legumes'),
('Missi Roti','Gram flour and wheat flatbread with fenugreek.','North Indian','Breads','vg','LD',10,15,4,'2 rotis (100g)',230,10,36,5,7,1,260,'gluten','diabetes|weight_loss|high_protein','regular','savory','besan|wheat|fenugreek','1 cup besan|1/2 cup whole wheat flour|2 tbsp kasuri methi|1 onion, finely chopped|1/2 tsp ajwain|Green chilli, coriander|Salt and water','Mix flours, spices, onion and herbs with salt|Knead into a firm dough with water and rest 15 minutes|Roll into rotis and cook on a hot tawa|Brush lightly with oil if desired','Lower glycemic than plain wheat roti.','grains'),
('Paneer Tikka','Grilled marinated paneer and peppers.','North Indian','Snack','v','SD',15,15,3,'6 pieces (150g)',260,18,8,17,2,4,420,'dairy','high_protein|diabetes','regular','spicy','paneer|capsicum|curd','200 g paneer cubes|1 capsicum, 1 onion, cut in squares|1/2 cup hung curd|1 tsp ginger-garlic paste|1 tsp tandoori masala, 1/2 tsp Kashmiri chilli|1 tsp lemon juice, 1 tsp oil|Salt, chaat masala','Whisk curd, spices, lemon, oil and salt|Toss paneer and vegetables in the marinade and rest 30 minutes|Thread on skewers and grill or air-fry at 200 C for 12-15 minutes|Sprinkle chaat masala and serve with mint chutney','Grilling avoids extra oil.','dairy'),
('Lauki Sabzi','Light bottle-gourd curry.','North Indian','Dal & Curry','vg','LD',10,15,3,'1 cup (180g)',90,2,10,5,3,4,260,'','weight_loss|heart|diabetes|hypertension|senior','soft','mild','bottle gourd|tomato|cumin','1 medium lauki, peeled and cubed|1 tomato|1/2 tsp cumin, pinch of asafoetida|1/4 tsp turmeric, 1/2 tsp coriander powder|1 green chilli, ginger|1 tsp oil|Coriander, salt','Heat oil and add cumin, asafoetida, ginger and chilli|Add lauki, turmeric and salt and mix|Add tomato and coriander powder, cover and cook 10 minutes|Garnish with coriander','Over 90 percent water - very light and gentle on digestion.','vegetables'),
('Tomato Shorba','Spiced Indian tomato soup.','North Indian','Soup & Salad','vg','LD',5,15,3,'1 cup (240ml)',70,2,12,2,2,6,320,'','weight_loss|heart|diabetes|hypertension|senior','soft','tangy|spicy','tomato|cumin|pepper','5 ripe tomatoes|1 small onion, 2 garlic cloves|1/2 tsp cumin, 4 peppercorns, 1 bay leaf|1 tsp besan (to thicken)|1 tsp oil|Coriander, salt','Boil tomatoes, onion and garlic in 2 cups water for 10 minutes and blend|Strain the puree|Temper cumin, pepper and bay leaf in oil, add besan and roast briefly|Add the tomato puree, simmer 5 minutes and season','A warm low-calorie starter.','vegetables'),
('Punjabi Kadhi','Tangy yogurt and gram-flour curry.','North Indian','Dal & Curry','v','LD',10,25,4,'1 cup (220g)',150,6,14,7,1,5,450,'dairy','senior','soft','tangy|mild','curd|besan|fenugreek','1 cup sour curd|3 tbsp besan|1/2 tsp turmeric|1 tsp fenugreek seeds, 1 tsp cumin|2 dry red chillies, curry leaves|1 tbsp oil|Salt, 3 cups water','Whisk curd, besan, turmeric, salt and water until smooth|Bring to a boil while stirring, then simmer 15 minutes|Temper fenugreek, cumin, red chillies and curry leaves in oil|Pour the tempering over the kadhi and serve with rice','Skip the fried pakoras for a lighter version.','dairy'),
('Egg Bhurji','Indian-style spiced scrambled eggs.','North Indian','Breakfast','e','BLD',5,10,2,'1 cup (150g)',220,14,5,16,1,2,420,'egg','high_protein|diabetes|weight_loss','soft','spicy|savory','egg|onion|tomato','4 eggs|1 onion, 1 tomato, finely chopped|1 green chilli|1/4 tsp turmeric, 1/2 tsp garam masala|1 tbsp oil|Coriander, salt','Saute onion and chilli in oil till soft|Add tomato and spices and cook 2 minutes|Pour in beaten eggs and scramble on low heat|Cook till just set and garnish with coriander','Ready in 15 minutes with 14 g protein.','eggs'),
